            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((color, cells))

    # Recolor objects nearest to the thin line-shaped colored indicators.
    indicators = []
    for color, cells in comps:
        ys = [r for r, c in cells]
        xs = [c for r, c in cells]
        hh, ww = max(ys)-min(ys)+1, max(xs)-min(xs)+1
        if len(cells) >= 3 and (hh == 1 or ww == 1):
            indicators.append((color, cells))

    indicator_sets = [set(cells) for _, cells in indicators]
    for color, cells in indicators:
        targets = []
        for oc, obj in comps:
            if any(set(obj) == s for s in indicator_sets):
                continue
            d = min(abs(r-y)+abs(c-x) for r,c in cells for y,x in obj)
            targets.append((d, obj))
        if targets:
            _, target = min(targets, key=lambda t:t[0])
            for r,c in target:
                out[r][c] = color
    return out
